		Select[31] :=LOCAL_LSP_GW_IN.CONTINGENCY_DATA_ARRAY[i].Select_List[1].30;
		Select[32] :=LOCAL_LSP_GW_IN.CONTINGENCY_DATA_ARRAY[i].Select_List[1].31;
		Select[33] :=LOCAL_LSP_GW_IN.CONTINGENCY_DATA_ARRAY[i].Select_List[2].0;
		Select[34] :=LOCAL_LSP_GW_IN.CONTINGENCY_DATA_ARRAY[i].Select_List[2].1;
		Select[35] :=LOCAL_LSP_GW_IN.CONTINGENCY_DATA_ARRAY[i].Select_List[2].2;
		Select[36] :=LOCAL_LSP_GW_IN.CONTINGENCY_DATA_ARRAY[i].Select_List[2].3;
